```javascript
// Suponha que `DictFaseTQ` seja o seu dicionário de fases a valores numéricos
var DictFaseTQ = ee.Dictionary({
  'CCDRU':1,
  'DECRETO':2,
  'NAO_INFORMADO':3,
  'PORTARIA':4,
  'RTID':5,
  'TITULADO':6,
  'TITULO_ANULADO':7,
  'TITULO_PARCIAL':8,
});

function criarImagemDeDicionario(dict) {
  // Iniciar uma imagem vazia
  var image = ee.Image();

  // Iterar sobre cada entrada do dicionário para adicionar bandas
  var keys = dict.keys();
  var values = dict.values();

  // Criar uma lista de imagens/bandas
  var imageList = keys.zip(values).map(function(pair) {
    var key = ee.String(pair.get(0));
    var value = ee.Number(pair.get(1));
    return ee.Image.constant(value).toInt().rename(key);
  });

